/**
 * Deterministic, transparent Ratna rules (Parashari framework). Nothing here
 * is generated by an LLM.
 *
 *  1. The Ascendant (Lagna) is calculated from the birth instant and place.
 *  2. PRIMARY: the Lagna lord's Ratna (the Lagna lord represents the whole
 *     chart; this is the most widely accepted starting point).
 *  3. ALTERNATIVE: the 5th or 9th house lord (trikona), only when that planet
 *     is not also the Lagna lord and owns no 6th, 8th or 12th house.
 *  4. CAUTION: every other planet whose chart-specific role argues against
 *     strengthening it: lords of the 6th/8th/12th (alone or mixed with a good
 *     house), mildly unfavourable 3rd/11th lords, the nodes (no house
 *     lordship) and Saturn's stone, which traditional sources treat with care.
 *  5. Each assessment carries the planet's real placement: sign, house,
 *     nakshatra and pada, dignity, retrograde, combustion, conjunctions,
 *     aspects, and the running Vimshottari dasha. A weak planet is never
 *     recommended merely for being weak.
 *
 * Other schools (Moon-sign, dasha-led, Shadbala-based) can reach different
 * conclusions. Strength scores (Shadbala, Ashtakavarga) are not calculated.
 */
import {
  GEMSTONES,
  STONE_FOR_PLANET,
  SIGNS,
  SIGN_LORD,
  PLANETS,
  type GemstoneInfo,
  type Planet,
  type Sign,
} from "./gemstone.catalogue.js";
import { wholeSignHouse, type BirthChart } from "./chart.engine.js";
import {
  DUSTHANA,
  KENDRA,
  TRIKONA,
  buildProfiles,
  functionalNature,
  housesOwnedBy,
  nakshatraOf,
  ordinalHouse as ordinal,
  vimshottari,
  type DashaResult,
  type Functional,
  type PlanetProfile,
} from "./analysis.js";

export { housesOwnedBy };

export interface ChartFactor {
  label: string;
  value: string;
}

export interface SecondaryPerspective {
  house: 5 | 9;
  planet: Planet;
  stone: GemstoneInfo;
  sign: Sign;
  reason: string;
}

export type RatnaCategory = "primary" | "alternative" | "caution";

/** One Ratna judged against the user's own chart. */
export interface StoneAssessment {
  stone: GemstoneInfo;
  planet: Planet;
  category: RatnaCategory;
  profile: PlanetProfile;
  functional: { nature: Functional; houses: number[]; reason: string };
  /** Chart-specific reasons for this category, each built from calculated facts. */
  reasons: string[];
  /** Chart-specific concerns about the planet itself. */
  cautions: string[];
  dashaNote: string | null;
}

export interface ChartAnalysis {
  lagna: { sign: Sign; degree: number; nakshatra: string; pada: number };
  moon: { sign: Sign; nakshatra: string; pada: number };
  dasha: DashaResult | null;
  profiles: Record<Planet, PlanetProfile>;
  primary: StoneAssessment;
  alternatives: StoneAssessment[];
  cautionedStones: StoneAssessment[];
  /** Planets with no chart-specific basis for or against their Ratna. */
  notIndicated: Planet[];
  /** Factors this engine does not calculate. */
  notCalculated: string[];
  /** Set when a few minutes' error could change the Ascendant sign. */
  ascendantNearBoundary: boolean;
}

export interface Recommendation {
  lagnaSign: Sign;
  lagnaLord: Planet;
  lagnaLordSign: Sign;
  lagnaLordHouse: number;
  primary: GemstoneInfo;
  secondary: SecondaryPerspective[];
  excluded: { house: 5 | 9; planet: Planet; reason: string }[];
  factors: ChartFactor[];
  cautions: string[];
  analysis: ChartAnalysis;
}

export const NOT_CALCULATED = [
  "Shadbala / Ashtakavarga (numeric planetary strength)",
  "Divisional charts (Navamsa and others)",
  "Temporal friendship and neecha-bhanga (cancellation of debilitation)",
  "Aspects cast by Rahu and Ketu",
];

const houseKinds = (h: number): string => {
  const k: string[] = [];
  if (KENDRA.includes(h)) k.push("kendra");
  if (TRIKONA.includes(h)) k.push("trikona");
  if (DUSTHANA.includes(h)) k.push("dusthana");
  if ([3, 6, 10, 11].includes(h)) k.push("upachaya");
  return k.length ? k.join("/") : "neutral house";
};

const SATURN_CAUTION =
  "Blue Sapphire is traditionally treated with particular caution; many practitioners suggest a trial period under qualified guidance.";

const MALEFICS: Planet[] = ["Saturn", "Mars", "Sun", "Rahu", "Ketu"];
const list = (ps: Planet[]) => ps.join(", ");

/** Chart-specific concerns about the planet itself (dignity, houses, combustion, affliction). */
const planetConcerns = (p: PlanetProfile): string[] => {
  const out: string[] = [];
  if (p.dignity === "debilitated") {
    out.push(`${p.planet} is in ${p.sign}, its sign of debilitation. Cancellation of debilitation (neecha-bhanga) is not calculated here, so a qualified astrologer should judge it.`);
  }
  if (p.dignity === "enemy sign") out.push(`${p.planet} is in ${p.sign}, a sign ruled by a natural enemy.`);
  if (DUSTHANA.includes(p.house)) out.push(`${p.planet} sits in the ${ordinal(p.house)} house, a dusthana; schools differ on how this affects its stone.`);
  if (p.combust) out.push(`${p.planet} is within the traditional combustion distance of the Sun.`);
  const bad = p.aspectedBy.filter((q) => MALEFICS.includes(q));
  const joined = p.conjunctions.filter((q) => MALEFICS.includes(q));
  if (joined.length) out.push(`${p.planet} is conjunct ${list(joined)}, traditionally malefic planets.`);
  if (bad.length) out.push(`${p.planet} receives the aspect of ${list(bad)}, traditionally malefic planets.`);
  return out;
};

const describePlacement = (p: PlanetProfile): string => {
  const bits = [
    `${p.planet} is in ${p.sign} (${p.degree.toFixed(1)}°) in the ${ordinal(p.house)} house (${houseKinds(p.house)})`,
    `in ${p.nakshatra} nakshatra, pada ${p.pada}`,
  ];
  let s = bits.join(", ");
  if (p.dignity !== "not assessed" && p.dignity !== "neutral sign") s += `; dignity: ${p.dignity}`;
  if (p.retrograde && p.planet !== "Rahu" && p.planet !== "Ketu") s += "; retrograde";
  return s + ".";
};

const dashaNoteFor = (planet: Planet, dasha: DashaResult | null): string | null => {
  if (!dasha) return null;
  const parts: string[] = [];
  if (dasha.mahadasha.lord === planet) parts.push(`${planet}'s Vimshottari Mahadasha is running (to ${dasha.mahadasha.end})`);
  if (dasha.antardasha.lord === planet) parts.push(`${planet}'s Antardasha is running (to ${dasha.antardasha.end})`);
  return parts.length ? parts.join("; ") + "." : null;
};

export const recommend = (chart: BirthChart, now: Date = new Date()): Recommendation => {
  const asc = chart.ascendant;
  const lagnaLord = SIGN_LORD[asc.sign];
  const instant = chart.instant;
  const profiles = buildProfiles(chart, instant ?? null);
  const dasha = instant ? vimshottari(chart.planets.Moon.longitude, instant, now) : null;
  const lordProfile = profiles[lagnaLord];
  const lordPos = chart.planets[lagnaLord];
  const lordHouse = wholeSignHouse(asc.signIndex, lordPos.signIndex);
  const primaryStone = STONE_FOR_PLANET[lagnaLord];
  const ascNak = nakshatraOf(asc.longitude);
  const moonNak = nakshatraOf(chart.planets.Moon.longitude);

  const factors: ChartFactor[] = [
    { label: "Ascendant (Lagna)", value: `${asc.sign} ${asc.degreeInSign.toFixed(1)}° (${ascNak.name}, pada ${ascNak.pada})` },
    { label: "Lagna lord", value: lagnaLord },
    { label: `${lagnaLord} placement`, value: `${lordPos.sign} (${ordinal(lordHouse)} house)` },
    { label: `${lagnaLord} nakshatra`, value: `${lordProfile.nakshatra}, pada ${lordProfile.pada}` },
  ];
  if (lordProfile.dignity !== "not assessed") factors.push({ label: "Dignity", value: `${lagnaLord} is in ${lordProfile.dignity === "exalted" || lordProfile.dignity === "debilitated" || lordProfile.dignity === "mooltrikona" ? "its " + (lordProfile.dignity === "exalted" ? "sign of exaltation" : lordProfile.dignity === "debilitated" ? "sign of debilitation" : "mooltrikona sign") : lordProfile.dignity}` });
  factors.push({ label: "Moon (Janma Rashi)", value: `${chart.planets.Moon.sign}, ${moonNak.name} pada ${moonNak.pada}` });
  if (dasha) {
    factors.push({
      label: "Current Vimshottari period",
      value: `${dasha.mahadasha.lord} Mahadasha / ${dasha.antardasha.lord} Antardasha (as of ${dasha.asOf})`,
    });
  }

  /* ---- Primary ---- */
  const primaryFunctional = functionalNature(lagnaLord, asc.signIndex);
  const primaryReasons = [
    `Your Ascendant is ${asc.sign}, ruled by ${lagnaLord}. The Lagna lord stands for the chart as a whole, so its Ratna is the traditional starting point.`,
    describePlacement(lordProfile),
    primaryFunctional.reason,
  ];
  if (lordProfile.conjunctions.length) primaryReasons.push(`${lagnaLord} shares ${lordProfile.sign} with ${list(lordProfile.conjunctions)}.`);
  if (lordProfile.aspectedBy.length) primaryReasons.push(`${lagnaLord} receives the aspect of ${list(lordProfile.aspectedBy)}.`);
  const primaryCautions = planetConcerns(lordProfile);
  if (lagnaLord === "Saturn") primaryCautions.push(SATURN_CAUTION);
  const ascendantNearBoundary = asc.degreeInSign < 1 || asc.degreeInSign > 29;
  if (ascendantNearBoundary) {
    primaryCautions.push(
      `Your Ascendant is only ${asc.degreeInSign < 1 ? asc.degreeInSign.toFixed(1) : (30 - asc.degreeInSign).toFixed(1)}° from a sign boundary. A birth-time error of a few minutes could change the Ascendant sign, and with it this recommendation.`,
    );
  }
  const primary: StoneAssessment = {
    stone: primaryStone,
    planet: lagnaLord,
    category: "primary",
    profile: lordProfile,
    functional: primaryFunctional,
    reasons: primaryReasons,
    cautions: primaryCautions,
    dashaNote: dashaNoteFor(lagnaLord, dasha),
  };

  /* ---- Alternatives and exclusions (5th / 9th lords) ---- */
  const secondary: SecondaryPerspective[] = [];
  const alternatives: StoneAssessment[] = [];
  const excluded: Recommendation["excluded"] = [];
  const decided = new Set<Planet>([lagnaLord]);
  for (const house of [5, 9] as const) {
    const sign = SIGNS[(asc.signIndex + house - 1) % 12];
    const planet = SIGN_LORD[sign];
    const owned = housesOwnedBy(planet, asc.signIndex);
    const dusthana = owned.filter((h) => DUSTHANA.includes(h));
    if (planet === lagnaLord) {
      excluded.push({ house, planet, reason: `${planet} rules the ${ordinal(house)} house and is already the Lagna lord.` });
    } else if (dusthana.length > 0) {
      excluded.push({
        house,
        planet,
        reason: `${planet} rules the ${ordinal(house)} house but also owns the ${dusthana.map(ordinal).join(" and ")} house, so it is excluded.`,
      });
    } else if (!decided.has(planet)) {
      decided.add(planet);
      const reason = `${planet} rules the ${ordinal(house)} house (${sign}) and owns no 6th, 8th or 12th house.`;
      secondary.push({ house, planet, stone: STONE_FOR_PLANET[planet], sign, reason });
      const prof = profiles[planet];
      alternatives.push({
        stone: STONE_FOR_PLANET[planet],
        planet,
        category: "alternative",
        profile: prof,
        functional: functionalNature(planet, asc.signIndex),
        reasons: [reason, describePlacement(prof), functionalNature(planet, asc.signIndex).reason],
        cautions: [...planetConcerns(prof), ...(planet === "Saturn" ? [SATURN_CAUTION] : [])],
        dashaNote: dashaNoteFor(planet, dasha),
      });
    }
  }

  /* ---- Cautioned and not-indicated Ratnas ---- */
  const cautionedStones: StoneAssessment[] = [];
  const notIndicated: Planet[] = [];
  for (const planet of PLANETS) {
    if (decided.has(planet)) continue;
    const fn = functionalNature(planet, asc.signIndex);
    const prof = profiles[planet];
    const reasons: string[] = [];
    if (fn.nature === "node") {
      reasons.push(
        `${planet} owns no sign, so this method has no house-lordship basis for ${STONE_FOR_PLANET[planet].name}. In this chart ${planet} is in the ${ordinal(prof.house)} house in ${prof.sign}.`,
        "Traditional sources generally advise using a node's Ratna only under qualified guidance.",
      );
    } else if (fn.nature === "malefic" || fn.nature === "mixed") {
      reasons.push(fn.reason);
      if (fn.nature === "mixed") reasons.push("Strengthening this planet would also strengthen its dusthana results, so it is cautioned rather than recommended.");
    } else if (planet === "Saturn") {
      reasons.push("Saturn's Ratna is treated with particular caution in traditional sources, whatever the chart.", fn.reason);
    }
    if (reasons.length === 0) {
      notIndicated.push(planet);
      continue;
    }
    cautionedStones.push({
      stone: STONE_FOR_PLANET[planet],
      planet,
      category: "caution",
      profile: prof,
      functional: fn,
      reasons,
      cautions: [describePlacement(prof)],
      dashaNote: dashaNoteFor(planet, dasha),
    });
  }

  return {
    lagnaSign: asc.sign,
    lagnaLord,
    lagnaLordSign: lordPos.sign,
    lagnaLordHouse: lordHouse,
    primary: primaryStone,
    secondary,
    excluded,
    factors,
    cautions: primaryCautions,
    analysis: {
      lagna: { sign: asc.sign, degree: Math.round(asc.degreeInSign * 10) / 10, nakshatra: ascNak.name, pada: ascNak.pada },
      moon: { sign: chart.planets.Moon.sign, nakshatra: moonNak.name, pada: moonNak.pada },
      dasha,
      profiles,
      primary,
      alternatives,
      cautionedStones,
      notIndicated,
      notCalculated: NOT_CALCULATED,
      ascendantNearBoundary,
    },
  };
};

export { GEMSTONES };
